export const DOMUtils={createTextWithBreaks(text){const fragment=document.createDocumentFragment();const lines=text.split('\n');lines.forEach((line,index)=>{fragment.appendChild(document.createTextNode(line));if(index<lines.length-1){fragment.appendChild(document.createElement('br'));}});return fragment;},createSpan(text,className=''){const span=document.createElement('span');span.textContent=text;if(className)span.className=className;return span;},createClickableRule(rule,onClick){const span=this.createSpan(rule,'simplified-rule');span.style.cursor='pointer';span.title='Click to apply this simplified rule';span.addEventListener('click',onClick);return span;},createSimplifiedRuleSuggestion(beforeText,rule,afterText,onRuleClick){const fragment=document.createDocumentFragment();if(beforeText){fragment.appendChild(this.createTextWithBreaks(beforeText));}
fragment.appendChild(document.createTextNode('Simplified rule: '));const ruleSpan=this.createClickableRule(rule,onRuleClick);fragment.appendChild(ruleSpan);if(afterText){fragment.appendChild(document.createElement('br'));fragment.appendChild(this.createTextWithBreaks(afterText));}
return fragment;},createWarning(message){return this.createTextWithBreaks(message);},clearElement(element){element.textContent='';},createTooltipContent(title,items,prefix='',columns=1){const container=document.createElement('div');container.className=`tooltip-content columns-${columns}`;const titleDiv=document.createElement('div');titleDiv.className='tooltip-title';titleDiv.textContent=title;container.appendChild(titleDiv);const itemsContainer=document.createElement('div');itemsContainer.className='tooltip-items';items.forEach(item=>{const itemDiv=document.createElement('div');itemDiv.className='tooltip-item';itemDiv.textContent=`${prefix}${item}`;itemsContainer.appendChild(itemDiv);});container.appendChild(itemsContainer);return container;},createCategoryButtonContent(category,hasWarning){const fragment=document.createDocumentFragment();fragment.appendChild(document.createTextNode(`@${category}`));if(hasWarning){const icon=document.createElement('span');icon.className='warning-icon';icon.textContent='⚠';fragment.appendChild(icon);}
return fragment;},createEmptyRuleSummary(totalAvailable){const fragment=document.createDocumentFragment();const strong=document.createElement('strong');strong.textContent='No ACL rule specified';fragment.appendChild(strong);fragment.appendChild(document.createElement('br'));const formattedTotal=totalAvailable.toLocaleString();fragment.appendChild(document.createTextNode(`All ${formattedTotal} commands are blocked by default`));return fragment;},createGrantedSummary(totalGranted,totalAvailable,percentage=null){const fragment=document.createDocumentFragment();const strong=document.createElement('strong');strong.textContent=totalGranted.toLocaleString();fragment.appendChild(strong);const formattedTotal=totalAvailable.toLocaleString();fragment.appendChild(document.createTextNode(` of ${formattedTotal} commands granted`));if(percentage){const span=document.createElement('span');span.className='text-muted';span.textContent=` (${percentage}%)`;fragment.appendChild(span);}
return fragment;},createCategorySection(category,commands,escapeHtml,formatNumber){const safeCategoryId=category.replace(/[^a-zA-Z0-9]/g,'-');const categoryId=`category-${safeCategoryId}`;const section=document.createElement('div');section.className='category-section';const header=document.createElement('div');header.className='category-header';header.setAttribute('role','button');header.setAttribute('tabindex','0');header.setAttribute('aria-expanded','true');header.setAttribute('data-category',safeCategoryId);header.onclick=()=>{import('../managers/category-manager.js').then(({default:CategoryManager})=>{CategoryManager.toggle(safeCategoryId);});};header.textContent=`${category} (${formatNumber(commands.length)})`;const commandsContainer=document.createElement('div');commandsContainer.className='category-commands';commandsContainer.id=categoryId;commands.forEach(cmd=>{const commandItem=document.createElement('div');commandItem.className='command-item';commandItem.setAttribute('title',`Command: ${escapeHtml(cmd.toUpperCase())}`);commandItem.textContent=cmd;commandsContainer.appendChild(commandItem);});section.appendChild(header);section.appendChild(commandsContainer);return section;},createNoCommandsMessage(){const p=document.createElement('p');p.className='text-muted';p.style.textAlign='center';p.style.padding='20px';p.textContent='No commands granted by this rule';return p;}};export default DOMUtils;